"""PDFTool — create real PDF files via ReportLab."""
from __future__ import annotations

import io
from typing import Any

from app.tools.base import Tool, ToolResult
from app.tools.office.outline import coerce_sections
from app.tools.office.result_store import ResultStore
from app.tools.office.runner import run_office_job


class PDFTool(Tool):
    name = "create_pdf"
    description = (
        "Create a PDF report with title and sections. "
        "Returns a download_url for the generated file."
    )
    input_schema = {
        "type": "object",
        "properties": {
            "title": {"type": "string"},
            "sections": {"type": "array"},
            "outline": {"type": "string"},
            "source_text": {"type": "string"},
            "filename": {"type": "string"},
            "task_id": {"type": "string"},
            "user_id": {"type": "string"},
        },
        "required": [],
    }
    permissions = frozenset({"filesystem:write"})

    def __init__(self, store: ResultStore) -> None:
        self._store = store

    async def execute(self, **kwargs: Any) -> ToolResult:
        title = str(kwargs.get("title") or "").strip() or "Report"
        outline = kwargs.get("outline")
        source_text = kwargs.get("source_text")
        sections_in = kwargs.get("sections")
        filename = str(kwargs.get("filename") or title or "report")

        if not kwargs.get("title") and not outline and not source_text and not sections_in:
            return ToolResult(
                success=False,
                error="Provide title, outline, source_text, or sections to create a PDF.",
                metadata={"status": "invalid_input"},
            )

        sections = coerce_sections(sections_in or outline, title=title, source_text=source_text)

        async def _build(_tid: str) -> tuple[bytes, str, str, dict[str, Any]]:
            data = _build_pdf(title=title, sections=sections)
            return data, filename, "pdf", {
                "sections": len(sections),
                "summary": f"Created PDF «{title}» with {len(sections)} sections.",
            }

        return await run_office_job(
            tool_name=self.name,
            store=self._store,
            build=_build,
            task_id=kwargs.get("task_id") if isinstance(kwargs.get("task_id"), str) else None,
            user_id=kwargs.get("user_id") if isinstance(kwargs.get("user_id"), str) else None,
        )


def _build_pdf(*, title: str, sections: list[dict[str, Any]]) -> bytes:
    from reportlab.lib.colors import HexColor
    from reportlab.lib.pagesizes import A4
    from reportlab.lib.styles import ParagraphStyle, getSampleStyleSheet
    from reportlab.lib.units import cm
    from reportlab.platypus import ListFlowable, ListItem, Paragraph, SimpleDocTemplate, Spacer

    buf = io.BytesIO()
    doc = SimpleDocTemplate(
        buf,
        pagesize=A4,
        leftMargin=2 * cm,
        rightMargin=2 * cm,
        topMargin=2 * cm,
        bottomMargin=2 * cm,
        title=title,
        author="NEXA AI",
    )
    styles = getSampleStyleSheet()
    title_style = ParagraphStyle(
        "NexaTitle",
        parent=styles["Title"],
        textColor=HexColor("#1E1B4B"),
        fontSize=22,
        spaceAfter=12,
    )
    h_style = ParagraphStyle(
        "NexaH",
        parent=styles["Heading2"],
        textColor=HexColor("#312E81"),
        fontSize=14,
        spaceBefore=14,
        spaceAfter=6,
    )
    body_style = ParagraphStyle(
        "NexaBody",
        parent=styles["BodyText"],
        fontSize=11,
        leading=15,
    )

    story: list[Any] = [
        Paragraph(_escape(title), title_style),
        Paragraph(_escape("Generated by NEXA AI (HEXARI)."), body_style),
        Spacer(1, 0.4 * cm),
    ]
    for section in sections:
        story.append(Paragraph(_escape(str(section.get("title") or "Section")), h_style))
        bullets = section.get("bullets") or []
        if bullets:
            items = [
                ListItem(Paragraph(_escape(str(b)), body_style), leftIndent=12)
                for b in bullets
            ]
            story.append(ListFlowable(items, bulletType="bullet", start="•"))
        else:
            story.append(Paragraph("&nbsp;", body_style))

    doc.build(story)
    data = buf.getvalue()
    if not data.startswith(b"%PDF"):
        raise ValueError("Generated PDF missing %PDF header.")
    if len(data) < 200:
        raise ValueError("Generated PDF appears too small to be valid.")
    return data


def _escape(text: str) -> str:
    return (
        text.replace("&", "&amp;")
        .replace("<", "&lt;")
        .replace(">", "&gt;")
    )


def verify_pdf_bytes(data: bytes) -> dict[str, Any]:
    from pypdf import PdfReader

    reader = PdfReader(io.BytesIO(data))
    texts = [(page.extract_text() or "") for page in reader.pages]
    return {"page_count": len(reader.pages), "text": "\n".join(texts)[:2000]}
